from pulp import *

# Define the problem
problem = LpProblem("Base_Station_Optimization", LpMinimize)

# Define the decision variables
base_stations = ['A', 'B', 'C']
users = [1, 2, 3, 4]
variables = {bs: {u: LpVariable(f'x_{bs}_{u}', lowBound=0) for u in users} for bs in base_stations}

# Define the parameters (example values, these need to be replaced with actual data)
link_qualities = {
    'A': {1: 2, 2: 3, 3: 1, 4: 2},
    'B': {1: 3, 2: 2, 3: 2, 4: 1},
    'C': {1: 1, 2: 2, 3: 3, 4: 2}
}
max_power = {'A': 20, 'B': 30, 'C': 40}
min_quality = {1: 20, 2: 30, 3: 40, 4: 50}

# Define the objective function
problem += lpSum(variables[bs][u] for bs in base_stations for u in users)

# Add constraints for user quality of service
for u in users:
    problem += lpSum(link_qualities[bs][u] * variables[bs][u] for bs in base_stations) >= min_quality[u]

# Add constraints for base station power capacity
for bs in base_stations:
    problem += lpSum(variables[bs][u] for u in users) <= max_power[bs]

# Solve the problem
solver = PULP_CBC_CMD()  # Choose the most suitable solver
result = solver.solve(problem)

# Output the results
if result == LpStatusOptimal:
    print("Optimal Power Allocation:")
    for bs in base_stations:
        for u in users:
            print(f"Power from {bs} to User{u}: {variables[bs][u].value():.2f}")
    print(f"Total Power Consumption: {problem.objective.value():.2f}")
else:
    print("No optimal solution found.")
